<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/audit.php'; requireRole('patient');
if ($_SERVER['REQUEST_METHOD'] !== 'POST' || !verifyCsrfToken($_POST['csrf_token'] ?? null)) { http_response_code(400); exit('Invalid consent request.'); }
$requestId = filter_input(INPUT_POST, 'request_id', FILTER_VALIDATE_INT); $decision = $_POST['decision'] ?? '';
$patientQuery = $pdo->prepare('SELECT id FROM patients WHERE user_id = :user_id LIMIT 1'); $patientQuery->execute([':user_id' => $_SESSION['user_id']]); $patientId = (int) $patientQuery->fetchColumn();
$requestQuery = $pdo->prepare('SELECT id, status, requested_by FROM consent_requests WHERE id = :id AND patient_id = :patient_id LIMIT 1'); $requestQuery->execute([':id' => $requestId, ':patient_id' => $patientId]); $request = $requestQuery->fetch(PDO::FETCH_ASSOC);
if (!$request || !in_array($decision, ['approved', 'denied', 'revoked'], true) || ($decision !== 'revoked' && $request['status'] !== 'pending') || ($decision === 'revoked' && $request['status'] !== 'approved')) { flash('danger', 'This consent action is not available.'); redirect('consent.php'); }
require_once __DIR__ . '/../includes/consent.php'; expireConsentRequests($pdo); if ($request['status'] === 'expired') { flash('warning', 'This consent request has expired.'); redirect('consent.php'); }
$update = $pdo->prepare('UPDATE consent_requests SET status = :status WHERE id = :id'); $update->execute([':status' => $decision, ':id' => $requestId]); $record = $pdo->prepare('INSERT INTO consent_records (consent_request_id, patient_id, decision) VALUES (:request_id, :patient_id, :decision)'); $record->execute([':request_id' => $requestId, ':patient_id' => $patientId, ':decision' => $decision]); $notification = $pdo->prepare('INSERT INTO notifications (user_id, title, message) VALUES (:user_id, :title, :message)'); $notification->execute([':user_id' => $request['requested_by'], ':title' => 'Consent ' . $decision, ':message' => 'Your patient consent request was ' . $decision . '.']); logAudit('CONSENT_' . strtoupper($decision), 'consent_request', $requestId, 'Patient ' . $decision . ' consent.'); flash('success', 'Consent ' . $decision . '.'); redirect('consent.php');